import type { Vault } from 'obsidian';
import type { ForgeLanguage } from '../i18n/localization';
import { FORGE_DOCUMENTATION_FILES_EN } from './documentationPackage.en.ts';

/**
 * Markdown documentation payload. Notes are written to the Vault only when
 * the user explicitly chooses Download documentation in plugin settings.
 */
export interface ForgeDocumentationFile {
  name: string;
  content: string;
}

/** Reject incomplete or ambiguous bundles before creating any Vault files. */
export function validateForgeDocumentationBundle(files: readonly ForgeDocumentationFile[]): void {
  const seenNames = new Set<string>();
  const issues: string[] = [];

  for (const [index, file] of files.entries()) {
    const name = typeof file?.name === 'string' ? file.name.trim() : '';
    const content = typeof file?.content === 'string' ? file.content : '';
    if (!name) issues.push(`entrada ${index + 1}: nome ausente`);
    else if (seenNames.has(name)) issues.push(`${name}: nome duplicado`);
    else seenNames.add(name);
    if (!content.trim()) issues.push(`${name || `entrada ${index + 1}`}: conteúdo vazio`);
  }

  if (issues.length > 0) {
    throw new Error(`Pacote de documentação incompleto ou inválido: ${issues.join('; ')}.`);
  }
}

export const DEFAULT_DOCUMENTATION_FOLDER = 'Statblock Forge/Documentation';
export const DEFAULT_PT_BR_DOCUMENTATION_FOLDER = 'Statblock Forge/Documentação';

